const draw: Variants = {
  hidden: { pathLength: 0, opacity: 0 },
  visible: (i: number) => {
    const delay = i * 0.5
    return {
      pathLength: 1,
      opacity: 1,
      transition: {
        pathLength: { delay, type: "spring", duration: 1.5, bounce: 0 },
        opacity: { delay, duration: 0.01 },
      },
    }
  },
}
const reveal: Variants = {
  hidden: { y: 50, opacity: 0 },
  visible: (i: number) => {
    const delay = i * 0.5
    return {
      y: 0,
      opacity: 1,
      transition: {
        y: { delay, type: "spring", duration: 0.8, bounce: 0.3 },
        opacity: { delay, duration: 0.3 },
      },
    }
  },
}

